export interface PromptOption {
  id: string;
  name: string;
  desc: string;
  prompt: string;
}

export interface Annotation {
  id: string;
  x: number;
  y: number;
  text: string;
  isOpen: boolean;
}

export interface ColorEdit {
  id: string;
  type: 'global' | 'fill';
  originX: number;
  originY: number;
  originColor: [number, number, number];
  tolerance: number;
  newColor: [number, number, number];
}

export interface SketchStroke {
  id: string;
  points: {x: number, y: number}[];
  color: string;
  width?: number;
}

export type LayerType = 'sketch' | 'vector' | 'render';

export interface LayerData {
  id: string;
  type: LayerType;
  images: string[];
  selectedIndex: number;
  annotations: Annotation[];
  colorEdits: ColorEdit[];
  sketchStrokes: SketchStroke[];
  promptDetails: string;
  wipe: number;
  compareMode: 'wipe' | 'fade' | 'blend';
  compareSource?: 'base' | 'sketch';
  interactionMode: 'pins' | 'recolor' | 'sketch' | 'fill' | 'eyedropper';
  hideEdits: boolean;
  editedImage: string | null;
  isGenerating: boolean;
  sourceImage?: string; 
  baseSketchImage?: string;
  isBlankCanvas?: boolean;
  canvasAspect?: string;
  canvasBgColor?: string;
  generationPrompt?: string;
  generationModel?: string;
  generationAspect?: string;
  generationTemp?: number;
  undoStack?: { sketchStrokes: SketchStroke[], colorEdits: ColorEdit[], annotations: Annotation[] }[];
  redoStack?: { sketchStrokes: SketchStroke[], colorEdits: ColorEdit[], annotations: Annotation[] }[];
}

export interface RenderSettings {
  aspectRatio: string;
  renderQuality: string;
  renderStyle: string;
  customAesthetic: string;
  renderBackground: boolean;
  model: string;
}

export const GRAYMAP_LEVELS = [25, 51, 76, 102, 127, 153, 178, 204, 229, 255];

import { ColorEdit, SketchStroke, PromptOption } from './types';

export const renderEditsToDataURL = async (originalSrc: string, edits: ColorEdit[], sketchStrokes: SketchStroke[] = []): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = "Anonymous";
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth;
      canvas.height = img.naturalHeight;
      const ctx = canvas.getContext('2d')!;
      ctx.drawImage(img, 0, 0);

      if (edits.length === 0 && sketchStrokes.length === 0) {
        return resolve(canvas.toDataURL('image/png', 1.0));
      }

      // Render strokes with UNIFORM scaling to prevent brush distortion
      if (sketchStrokes.length > 0) {
        sketchStrokes.forEach(stroke => {
          if (!stroke.points || stroke.points.length === 0) return;
          ctx.beginPath();
          ctx.strokeStyle = stroke.color;

          // Use the master unit (Percent of Width/Height) but draw in pixels
          const scaleW = canvas.width / 100;
          const scaleH = canvas.height / 100;

          // Use a fixed scale for line width based on the average dimension to keep it looking consistent
          const baseScale = (canvas.width + canvas.height) / 200;
          ctx.lineWidth = (stroke.width || 0.5) * baseScale;
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';

          ctx.moveTo(stroke.points[0].x * scaleW, stroke.points[0].y * scaleH);
          for (let i = 1; i < stroke.points.length; i++) {
            ctx.lineTo(stroke.points[i].x * scaleW, stroke.points[i].y * scaleH);
          }
          ctx.stroke();
        });
      }

      if (edits.length > 0) {
        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const data = imageData.data;

        for (const edit of edits) {
          const { type, originX, originY, originColor, tolerance, newColor } = edit;
          const [r0, g0, b0] = originColor;

          if (type === 'global') {
            for (let i = 0; i < data.length; i += 4) {
              const r = data[i];
              const g = data[i+1];
              const b = data[i+2];
              if (Math.abs(r - r0) <= tolerance && Math.abs(g - g0) <= tolerance && Math.abs(b - b0) <= tolerance) {
                data[i] = newColor[0];
                data[i+1] = newColor[1];
                data[i+2] = newColor[2];
              }
            }
          } else if (type === 'fill') {
            const startX = originX;
            const startY = originY;
            if (startX < 0 || startX >= canvas.width || startY < 0 || startY >= canvas.height) continue;

            const startPos = (startY * canvas.width + startX) * 4;
            const sr = data[startPos], sg = data[startPos+1], sb = data[startPos+2];
            if (Math.abs(sr - r0) > tolerance || Math.abs(sg - g0) > tolerance || Math.abs(sb - b0) > tolerance) {
               continue;
            }

            const visited = new Uint8Array(canvas.width * canvas.height);
            const stack = [startX, startY];

            while(stack.length > 0) {
              const y = stack.pop()!;
              const x = stack.pop()!;
              const idx = y * canvas.width + x;
              if (visited[idx]) continue;
              visited[idx] = 1;

              const p = idx * 4;
              const r = data[p], g = data[p+1], b = data[p+2];
              if (Math.abs(r - r0) <= tolerance && Math.abs(g - g0) <= tolerance && Math.abs(b - b0) <= tolerance) {
                 data[p] = newColor[0];
                 data[p+1] = newColor[1];
                 data[p+2] = newColor[2];

                 if (x > 0) { stack.push(x-1, y); }
                 if (x < canvas.width - 1) { stack.push(x+1, y); }
                 if (y > 0) { stack.push(x, y-1); }
                 if (y < canvas.height - 1) { stack.push(x, y+1); }
              }
            }
          }
        }
        ctx.putImageData(imageData, 0, 0);
      }

      resolve(canvas.toDataURL('image/png', 1.0));
    };
    img.src = originalSrc;
  });
};

export const createCompositeDataURL = async (
  baseSrc: string,
  overlaySrc: string,
  wipeVal: number,
  compMode: 'wipe' | 'fade' | 'blend',
  sketchStrokes: SketchStroke[] = []
): Promise<string> => {
  return new Promise((resolve) => {
    const baseImg = new Image();
    const overImg = new Image();
    baseImg.crossOrigin = "Anonymous";
    overImg.crossOrigin = "Anonymous";

    baseImg.onload = () => {
      overImg.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = baseImg.naturalWidth;
        canvas.height = baseImg.naturalHeight;
        const ctx = canvas.getContext('2d')!;

        // 1. Draw base (the current result/render)
        ctx.drawImage(baseImg, 0, 0);

        // 2. Composite the overlay source based on mode
        ctx.save();
        if (compMode === 'wipe') {
          // Calculate clip area to match UI (right portion visible)
          const wipePx = (wipeVal / 100) * canvas.width;
          ctx.beginPath();
          ctx.rect(wipePx, 0, canvas.width - wipePx, canvas.height);
          ctx.clip();
          ctx.drawImage(overImg, 0, 0, canvas.width, canvas.height);
        } else if (compMode === 'fade') {
          ctx.globalAlpha = (100 - wipeVal) / 100;
          ctx.drawImage(overImg, 0, 0, canvas.width, canvas.height);
        } else if (compMode === 'blend') {
          ctx.globalAlpha = (100 - wipeVal) / 100;
          ctx.globalCompositeOperation = 'multiply';
          ctx.drawImage(overImg, 0, 0, canvas.width, canvas.height);
        }
        ctx.restore();

        // 3. Draw strokes on top if they aren't already baked in
        // Note: App.tsx editedImage logic usually bakes them, but adding them here 
        // ensures the VERY latest strokes (real-time) are included in the capture.
        if (sketchStrokes.length > 0) {
          sketchStrokes.forEach(stroke => {
            if (!stroke.points || stroke.points.length === 0) return;
            ctx.beginPath();
            ctx.strokeStyle = stroke.color;
            const scaleW = canvas.width / 100;
            const scaleH = canvas.height / 100;
            const baseScale = (canvas.width + canvas.height) / 200;
            ctx.lineWidth = (stroke.width || 0.5) * baseScale;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.moveTo(stroke.points[0].x * scaleW, stroke.points[0].y * scaleH);
            for (let i = 1; i < stroke.points.length; i++) {
              ctx.lineTo(stroke.points[i].x * scaleW, stroke.points[i].y * scaleH);
            }
            ctx.stroke();
          });
        }

        resolve(canvas.toDataURL('image/png'));
      };
      overImg.src = overlaySrc;
    };
    baseImg.src = baseSrc;
  });
};

export const VECTOR_PROMPTS: PromptOption[] = [
  {
    id: 'tech-vec-materials',
    name: 'Material-Mapped Vector',
    desc: 'Technical vector that groups identical materials under shared grayscale tones.',
    prompt: 'Transform this rough sketch into a clean, precise technical illustration. Take a tiny bit of creative liberty to enhance the structural design, but strictly RESPECT the original shape, composition, and spatial arrangement overall. Do not rotate, flip, or rearrange elements. Convert the rough lines into crisp, continuous vector-style line art. Remove all messy construction lines and organic shading. CRITICAL: Analyze the geometric segments and infer their physical materials. Fill these segments with flat, solid grayscale tones using this rule: segments that share the SAME material must use the EXACT SAME grayscale tone. Segments of DIFFERENT materials must use DIFFERENT grayscale tones to clearly separate them visually. Key materials should be immediately identifiable by their distinct grayscale grouping. The final image should be a polished, flat-color vectorized blueprint with zero gradients.'
  }
];

export const getClosestAspectRatio = async (src: string): Promise<string> => {
   return new Promise((resolve) => {
     const img = new Image();
     img.onload = () => {
        const ratio = img.naturalWidth / img.naturalHeight;
        const choices = {
          "1:1": 1,
          "4:3": 4/3,
          "3:4": 3/4,
          "16:9": 16/9,
          "9:16": 9/16,
          "4:1": 4,
          "1:4": 1/4
        };
        let closest = "1:1";
        let minDiff = Infinity;
        for (const [key, val] of Object.entries(choices)) {
           const diff = Math.abs(val - ratio);
           if (diff < minDiff) {
              minDiff = diff;
              closest = key;
           }
        }
        resolve(closest);
     };
     img.src = src;
   });
};

