import React, { useState, useRef, useEffect } from 'react';

export type TransformState = { scale: number, x: number, y: number };

interface PanZoomProps {
  children: React.ReactNode;
  className?: string;
  transform?: TransformState;
  setTransform?: React.Dispatch<React.SetStateAction<TransformState>>;
}

export const PanZoom = ({ children, className = '', transform: extTransform, setTransform: extSetTransform }: PanZoomProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [intTransform, setIntTransform] = useState<TransformState>({ scale: 1, x: 0, y: 0 });
  const dragging = useRef(false);
  const moved = useRef(false);
  const startPos = useRef({ x: 0, y: 0 });

  const transform = extTransform ?? intTransform;
  const setTransform = extSetTransform ?? setIntTransform;

  const spacePressed = useRef(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      if (e.code === 'Space') {
        e.preventDefault();
        spacePressed.current = true;
        if (containerRef.current) containerRef.current.style.cursor = 'grab';
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'Space') {
        spacePressed.current = false;
        if (containerRef.current && !dragging.current) containerRef.current.style.cursor = '';
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    const container = containerRef.current;
    if (!container) return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };

    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      setTransform(prev => {
        if (e.ctrlKey || e.metaKey) {
          const delta = e.deltaY;
          const newScale = Math.min(Math.max(0.1, prev.scale * Math.exp(-delta * 0.01)), 40);
          const rect = container.getBoundingClientRect();
          const cx = rect.width / 2;
          const cy = rect.height / 2;
          const mouseX = e.clientX - rect.left;
          const mouseY = e.clientY - rect.top;

          const newX = mouseX - cx - (mouseX - cx - prev.x) * (newScale / prev.scale);
          const newY = mouseY - cy - (mouseY - cy - prev.y) * (newScale / prev.scale);
          return { scale: newScale, x: newX, y: newY };
        } else {
          return {
            ...prev,
            x: prev.x - e.deltaX * 1.5,
            y: prev.y - e.deltaY * 1.5
          };
        }
      });
    };

    container.addEventListener('wheel', handleWheel, { passive: false });
    const preventDrag = (e: Event) => e.preventDefault();
    container.addEventListener('dragstart', preventDrag);

    return () => {
       container.removeEventListener('wheel', handleWheel);
       container.removeEventListener('dragstart', preventDrag);
       window.removeEventListener('keydown', handleKeyDown);
       window.removeEventListener('keyup', handleKeyUp);
    };
  }, [setTransform]);

  const onPointerDown = (e: React.PointerEvent) => {
    const isModifierKey = e.shiftKey || e.button === 1 || spacePressed.current; // Middle click, shift, or space
    if (!isModifierKey && (e.target as HTMLElement).closest('button, input, textarea, .annotation-node, .no-drag')) return;
    dragging.current = true;
    moved.current = false;
    startPos.current = { x: e.clientX - transform.x, y: e.clientY - transform.y };
    if (containerRef.current) containerRef.current.style.cursor = 'grabbing';
  };

  const onPointerMove = (e: React.PointerEvent) => {
    if (!dragging.current) return;
    moved.current = true;
    setTransform(prev => ({
      ...prev,
      x: e.clientX - startPos.current.x,
      y: e.clientY - startPos.current.y
    }));
  };

  const onPointerUp = () => {
    dragging.current = false;
    if (containerRef.current) containerRef.current.style.cursor = '';
  };

  const onClickCapture = (e: React.MouseEvent) => {
    if (moved.current) {
      e.stopPropagation();
      e.preventDefault();
      moved.current = false;
    }
  };

  return (
    <div 
      ref={containerRef}
      className={`relative w-full h-full overflow-hidden min-w-0 min-h-0 flex items-center justify-center select-none ${className}`}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerLeave={onPointerUp}
      onClickCapture={onClickCapture}
      onDoubleClick={() => setTransform({ scale: 0.7, x: 0, y: 0 })}
    >
      <div 
        style={{ 
          transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})`,
          transformOrigin: 'center',
        }}
      >
        {children}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { Upload, Wand2, Settings2, ChevronDown, CheckCircle2, CircleDashed, Loader2, X, Check, Pipette, MapPin, Undo2, Redo2, Eye, EyeOff, Layers, SlidersHorizontal, Camera, Download, Pencil, Trash2, PaintBucket, SplitSquareHorizontal, Blend, PenTool, Sparkles, Image as ImageIcon } from 'lucide-react';
import { PanZoom } from './PanZoom';
import { LayerData, RenderSettings, GRAYMAP_LEVELS, SketchStroke } from './types';
import { RENDER_STYLES, BASE_RENDER_CONSTRAINT } from './utils';

interface Props {
  layer: LayerData;
  index: number;
  isActive: boolean;
  fileInputRef: React.RefObject<HTMLInputElement | null>;
  isDragging: boolean;
  setIsDragging: (d: boolean) => void;
  processFile: (f: File) => void;
  scrollToLayer: (i: number) => void;
  executeVector: (id: string, customPrompt?: string) => void;
  executeRender: (id: string) => void;
  generateAlternatives: (id: string) => void;
  updateLayer: (id: string, updates: Partial<LayerData>) => void;
  renderSettings: RenderSettings;
  setRenderSettings: React.Dispatch<React.SetStateAction<RenderSettings>>;
  handlePointerDown: (e: React.PointerEvent<HTMLDivElement>, l: LayerData) => void;
  handlePointerMove: (e: React.PointerEvent<HTMLDivElement>, l: LayerData) => void;
  handlePointerUp: (e: React.PointerEvent<HTMLDivElement>, l: LayerData) => void;
  handlePointerCancel: (e: React.PointerEvent<HTMLDivElement>, l: LayerData) => void;
  handleImageClick: (e: React.MouseEvent<HTMLDivElement>, l: LayerData) => void;
  captureScreenshot: (id: string) => void;
  downloadFullImage: (src: string, layer: LayerData) => void;
  imageRefs: React.MutableRefObject<Record<string, HTMLImageElement | null>>;
  strokeColor: string;
  setStrokeColor: (c: string) => void;
  strokeWidth: number;
  setStrokeWidth: (w: number) => void;
  activeEditId: string | null;
  setActiveEditId: (id: string | null) => void;
  deleteEdit: (layerId: string, id: string) => void;
  deleteAnnotation: (layerId: string, id: string) => void;
  updateAnnotationText: (layerId: string, id: string, text: string) => void;
  toggleAnnotationOpen: (layerId: string, id: string, state?: boolean) => void;
  undo: (layerId: string) => void;
  redo: (layerId: string) => void;
  panZoomTransform?: { scale: number, x: number, y: number };
  setPanZoomTransform?: React.Dispatch<React.SetStateAction<{ scale: number, x: number, y: number }>>;
}

export const LayerSection: React.FC<Props> = (props) => {
  const { layer, index, isActive, isDragging, setIsDragging, executeVector, executeRender, generateAlternatives, updateLayer, renderSettings, setRenderSettings, handlePointerDown, handlePointerMove, handlePointerUp, handlePointerCancel, handleImageClick, captureScreenshot, downloadFullImage, imageRefs, strokeColor, setStrokeColor, strokeWidth, setStrokeWidth, deleteAnnotation, updateAnnotationText, toggleAnnotationOpen, undo, redo, panZoomTransform, setPanZoomTransform } = props;

  const [canvasAspect, setCanvasAspect] = useState<string>('original');
  const [canvasBgColor, setCanvasBgColor] = useState<string>('#ffffff');
  const [isEnhancing, setIsEnhancing] = useState(false);
  const localInputRef = useRef<HTMLInputElement>(null);

  const handleUpdate = (updates: Partial<LayerData>) => updateLayer(layer.id, updates);
  const selectedImage = layer.images[layer.selectedIndex] || null;
  const displayedImage = (!layer.hideEdits && layer.editedImage) ? layer.editedImage : selectedImage;
  const compSource = layer.compareSource || 'base';
  const sourceImg = (compSource === 'sketch' && layer.baseSketchImage) ? layer.baseSketchImage : (layer.sourceImage || layer.images[0]);
  const wipeVal = layer.wipe;
  const compMode = layer.compareMode;

  const getDimensionsFromAspect = (aspect: string, imgWidth?: number, imgHeight?: number) => {
    switch(aspect) {
      case '16:9': return { w: 1024, h: 576 };
      case '9:16': return { w: 576, h: 1024 };
      case '4:3': return { w: 1024, h: 768 };
      case '3:4': return { w: 768, h: 1024 };
      case '1:1': return { w: 1024, h: 1024 };
      case 'original':
      default:
        if (imgWidth && imgHeight) return { w: imgWidth, h: imgHeight };
        return { w: 1024, h: 1024 };
    }
  };

  const prevAspectRef = useRef<string | undefined>(layer.canvasAspect);
  useEffect(() => {
    if (layer.isBlankCanvas && layer.type === 'sketch' && layer.images.length > 0) {
      const oldAspect = prevAspectRef.current || 'original';
      const newAspect = layer.canvasAspect || '1:1';

      if (oldAspect !== newAspect) {
        const oldDims = getDimensionsFromAspect(oldAspect);
        const newDims = getDimensionsFromAspect(newAspect);

        if (layer.sketchStrokes.length > 0) {
          const transformedStrokes = layer.sketchStrokes.map(stroke => ({
            ...stroke,
            points: stroke.points.map(p => {
              const oldW = oldDims.w;
              const oldH = oldDims.h;
              const px = p.x * oldW / 100;
              const py = p.y * oldH / 100;
              const newW = newDims.w;
              const newH = newDims.h;
              const offsetX = (newW - oldW) / 2;
              const offsetY = (newH - oldH) / 2;
              const newPx = px + offsetX;
              const newPy = py + offsetY;
              return { x: (newPx / newW) * 100, y: (newPy / newH) * 100 };
            })
          }));

          const canvas = document.createElement('canvas');
          canvas.width = newDims.w; canvas.height = newDims.h;
          const ctx = canvas.getContext('2d');
          if (ctx) {
            ctx.fillStyle = layer.canvasBgColor || '#ffffff';
            ctx.fillRect(0, 0, newDims.w, newDims.h);
            const newImg = canvas.toDataURL('image/png');
            updateLayer(layer.id, { images: [newImg], sketchStrokes: transformedStrokes });
          }
        } else {
          const canvas = document.createElement('canvas');
          canvas.width = newDims.w; canvas.height = newDims.h;
          const ctx = canvas.getContext('2d');
          if (ctx) {
            ctx.fillStyle = layer.canvasBgColor || '#ffffff';
            ctx.fillRect(0, 0, newDims.w, newDims.h);
            updateLayer(layer.id, { images: [canvas.toDataURL('image/png')] });
          }
        }
        prevAspectRef.current = newAspect;
      } else {
        const { w, h } = getDimensionsFromAspect(newAspect);
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = layer.canvasBgColor || '#ffffff';
          ctx.fillRect(0, 0, w, h);
          const newImg = canvas.toDataURL('image/png');
          if (newImg !== layer.images[0]) {
            updateLayer(layer.id, { images: [newImg] });
          }
        }
      }
    }
  }, [layer.canvasAspect, layer.canvasBgColor, layer.isBlankCanvas, layer.id, layer.type]);

  const processLocalFile = (file: File) => {
    if (file && file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          const { w, h } = getDimensionsFromAspect(canvasAspect, img.width, img.height);
          const canvas = document.createElement('canvas');
          canvas.width = w; canvas.height = h;
          const ctx = canvas.getContext('2d');
          if (ctx) {
            ctx.fillStyle = canvasBgColor;
            ctx.fillRect(0, 0, w, h);
            const scale = Math.min(w / img.width, h / img.height);
            const dw = img.width * scale;
            const dh = img.height * scale;
            const dx = (w - dw) / 2;
            const dy = (h - dh) / 2;
            ctx.drawImage(img, dx, dy, dw, dh);
            setPanZoomTransform?.({ scale: 0.7, x: 0, y: 0 });
            updateLayer(layer.id, { images: [canvas.toDataURL('image/png')], selectedIndex: 0, interactionMode: 'sketch', isBlankCanvas: false });
          }
        };
        img.src = e.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGallerySelect = async () => {
    const media = await Flow.media.select({ filter: 'image' });
    if (media) {
      const dataUrl = `data:${media.mimeType};base64,${media.base64}`;
      const img = new Image();
      img.onload = () => {
        const { w, h } = getDimensionsFromAspect(canvasAspect, img.width, img.height);
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.fillStyle = canvasBgColor;
          ctx.fillRect(0, 0, w, h);
          const scale = Math.min(w / img.width, h / img.height);
          const dw = img.width * scale;
          const dh = img.height * scale;
          const dx = (w - dw) / 2;
          const dy = (h - dh) / 2;
          ctx.drawImage(img, dx, dy, dw, dh);
          setPanZoomTransform?.({ scale: 0.7, x: 0, y: 0 });
          updateLayer(layer.id, { images: [canvas.toDataURL('image/png')], selectedIndex: 0, interactionMode: 'sketch', isBlankCanvas: false });
        }
      };
      img.src = dataUrl;
    }
  };

  const handleWebcamCapture = async () => {
    try {
      const photo = await Flow.camera.capture();
      if (photo) {
        const dataUrl = `data:${photo.mimeType};base64,${photo.base64}`;
        const img = new Image();
        img.onload = () => {
          const { w, h } = getDimensionsFromAspect(canvasAspect, img.width, img.height);
          const canvas = document.createElement('canvas');
          canvas.width = w; canvas.height = h;
          const ctx = canvas.getContext('2d');
          if (ctx) {
            ctx.fillStyle = canvasBgColor;
            ctx.fillRect(0, 0, w, h);
            const scale = Math.min(w / img.width, h / img.height);
            const dw = img.width * scale;
            const dh = img.height * scale;
            const dx = (w - dw) / 2;
            const dy = (h - dh) / 2;
            ctx.drawImage(img, dx, dy, dw, dh);
            setPanZoomTransform?.({ scale: 0.7, x: 0, y: 0 });
            updateLayer(layer.id, { images: [canvas.toDataURL('image/png')], selectedIndex: 0, interactionMode: 'sketch', isBlankCanvas: false });
          }
        };
        img.src = dataUrl;
      }
    } catch (e) {
      console.error("Camera capture failed", e);
    }
  };

  const handleEnhanceCustomPrompt = async () => {
    if (!renderSettings.customAesthetic.trim()) return;
    setIsEnhancing(true);
    try {
      const { text } = await Flow.generate.text(
        `Flesh out the following brief aesthetic description into a high-quality, descriptive prompt for an image rendering model. Focus on materials, lighting, and technical execution. Keep the response to a single paragraph. Original description: ${renderSettings.customAesthetic}`,
        { thinkingLevel: 'medium' }
      );
      if (text) {
        setRenderSettings(prev => ({ ...prev, customAesthetic: text.trim() }));
      }
    } catch (e) {
      console.error("Failed to enhance prompt", e);
    } finally {
      setIsEnhancing(false);
    }
  };

  return (
    <section id={`stage-${index}`} className={`w-full h-full relative flex items-center justify-center`}>
      <div className="absolute inset-0 w-full h-full flex flex-col lg:flex-row items-stretch relative">
        <div className="flex-1 w-full relative flex flex-col items-center justify-center min-w-0 min-h-0 overflow-hidden">

          {layer.images.length === 0 ? (
            layer.type === 'sketch' ? (
              <div 
                onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
                onDrop={(e) => { e.preventDefault(); setIsDragging(false); if(e.dataTransfer.files?.[0]) processLocalFile(e.dataTransfer.files[0]); }}
                className={`w-full h-full flex flex-col items-center justify-center transition-all ${isDragging ? 'bg-white/5' : ''}`}
              >
                <div className="flex flex-col items-center max-w-lg w-full px-6">
                    <div className="text-center mb-10">
                      <p className="text-[10px] uppercase tracking-[0.2em] font-mono text-white max-w-sm mx-auto leading-relaxed">
                        input your sketch to refine it into a high fidelity render
                      </p>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 w-full mb-8">
                      <button onClick={() => localInputRef.current?.click()} className="group flex flex-col items-center justify-center p-6 rounded-xl border border-border/50 hover:border-white/30 hover:bg-white/5 transition-all cursor-pointer bg-black/20 shadow-xl">
                        <div className="w-12 h-12 rounded-full bg-white/5 border border-border/50 flex items-center justify-center mb-4 group-hover:scale-110 group-hover:bg-white/10 transition-all">
                          <Upload size={18} className="text-[#888] group-hover:text-white transition-colors" />
                        </div>
                        <span className="text-[9px] uppercase tracking-[0.2em] font-mono text-[#666] group-hover:text-[#888] text-center">Local File</span>
                        <input type="file" ref={localInputRef} className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && processLocalFile(e.target.files[0])} />
                      </button>
                      <button onClick={handleGallerySelect} className="group flex flex-col items-center justify-center p-6 rounded-xl border border-border/50 hover:border-white/30 hover:bg-white/5 transition-all cursor-pointer bg-black/20 shadow-xl">
                        <div className="w-12 h-12 rounded-full bg-white/5 border border-border/50 flex items-center justify-center mb-4 group-hover:scale-110 group-hover:bg-white/10 transition-all">
                          <ImageIcon size={18} className="text-[#888] group-hover:text-white transition-colors" />
                        </div>
                        <span className="text-[9px] uppercase tracking-[0.2em] font-mono text-[#666] group-hover:text-[#888] text-center">Media Gallery</span>
                      </button>
                      <button onClick={handleWebcamCapture} className="group flex flex-col items-center justify-center p-6 rounded-xl border border-border/50 hover:border-white/30 hover:bg-white/5 transition-all cursor-pointer bg-black/20 shadow-xl">
