                          <Camera size={18} className="text-[#888] group-hover:text-white transition-colors" />
                        </div>
                        <span className="text-[9px] uppercase tracking-[0.2em] font-mono text-[#666] group-hover:text-[#888] text-center">Webcam Snapshot</span>
                      </button>
                    </div>
                    <div className="w-full flex items-center gap-4 mb-8 px-8">
                      <div className="flex-1 h-px bg-white/10"></div>
                      <span className="text-[9px] uppercase tracking-[0.3em] font-mono text-[#444]">Or Start Fresh</span>
                      <div className="flex-1 h-px bg-white/10"></div>
                    </div>
                    <button 
                      onClick={(e) => {
                          e.stopPropagation(); e.preventDefault();
