                          canvas.width = w; canvas.height = h;
                          const ctx = canvas.getContext('2d');
                          if(ctx) { ctx.fillStyle = canvasBgColor; ctx.fillRect(0,0,w,h); }
                          updateLayer(layer.id, { images: [canvas.toDataURL('image/png')], selectedIndex: 0, interactionMode: 'sketch', isBlankCanvas: true, canvasAspect: canvasAspect, canvasBgColor: canvasBgColor });
                      }}
                      className="w-full py-4 border border-border/50 rounded-xl text-[10px] font-bold uppercase tracking-[0.2em] text-[#aaa] hover:text-black hover:border-white transition-all hover:bg-white flex items-center justify-center gap-3 group shadow-lg"
                    >
                      <Pencil size={14} className="text-[#888] group-hover:text-black transition-colors"/> Create sketch from blank canvas
                    </button>
                </div>
              </div>
            ) : (
                <div className="flex flex-col items-center gap-4 opacity-30 text-text-dim">
                  <CircleDashed size={48} className={layer.isGenerating ? "animate-spin-slow" : ""} />
                  <span className="text-[10px] uppercase tracking-[0.2em] font-mono">
                     {layer.isGenerating ? `Generating ${layer.type === 'render' ? 'Render' : 'Vector'} Batch...` : 'Awaiting Content'}
                  </span>
                </div>
            )
          ) : (
            <div className="w-full flex-1 relative min-w-0 min-h-0 overflow-hidden select-none" id={`layer-panzoom-${layer.id}`}>
