                {(layer.type === 'vector' || layer.type === 'sketch' || layer.type === 'render') && (
                  <>
                    {layer.type !== 'render' && (
                      <button onClick={() => handleUpdate({ interactionMode: 'sketch' })} className={`px-4 py-1.5 rounded-full text-[10px] font-bold tracking-wider flex items-center gap-1.5 transition-all ${layer.interactionMode === 'sketch' ? 'bg-white text-black shadow-[0_0_12px_rgba(255,255,255,0.3)]' : 'text-text-dim hover:text-white'}`}><Pencil size={12}/> Sketch</button>
                    )}
                    {(layer.interactionMode === 'sketch' || layer.interactionMode === 'fill' || layer.interactionMode === 'eyedropper') && (
                        <div className="flex items-center gap-2 mx-2">
                           <div className="text-[9px] uppercase font-mono tracking-widest text-[#777]">Color</div>
                           <label className={`w-5 h-5 flex items-center justify-center rounded-full border border-white/20 shadow-inner hover:scale-110 transition-transform cursor-pointer relative overflow-hidden ring-1 ring-white/10`} style={{ backgroundColor: strokeColor }}>
                             <input type="color" value={strokeColor} onChange={e => setStrokeColor(e.target.value)} className="opacity-0 absolute inset-0 w-full h-full cursor-pointer" />
                           </label>
