                    {(layer.interactionMode === 'sketch') && (
                        <div className="flex items-center gap-2 mx-2">
                           <div className="text-[9px] uppercase font-mono tracking-widest text-[#777]">Size</div>
                           <input type="range" min="0.1" max="5" step="0.1" value={strokeWidth} onChange={e => setStrokeWidth(parseFloat(e.target.value))} className="w-16 appearance-none bg-[#333] h-[3px] rounded-full outline-none [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3 [&::-webkit-slider-thumb]:h-3 [&::-webkit-slider-thumb]:bg-white [&::-webkit-slider-thumb]:rounded-full cursor-ew-resize hover:bg-[#444] transition-colors" />
                        </div>
                    )}
                    <button onClick={() => handleUpdate({ interactionMode: 'pins' })} className={`px-4 py-1.5 rounded-full text-[10px] font-bold tracking-wider flex items-center gap-1.5 transition-all ${layer.interactionMode === 'pins' ? 'bg-white text-black shadow-[0_0_12px_rgba(255,255,255,0.3)]' : 'text-text-dim hover:text-white'}`}><MapPin size={12}/> Annotate</button>
                    {(layer.type === 'vector' || layer.type === 'sketch') && (
                      <button onClick={() => handleUpdate({ interactionMode: 'fill' })} className={`px-4 py-1.5 rounded-full text-[10px] font-bold tracking-wider flex items-center gap-1.5 transition-all ${layer.interactionMode === 'fill' ? 'bg-white text-black shadow-[0_0_12px_rgba(255,255,255,0.3)]' : 'text-text-dim hover:text-white'}`}><PaintBucket size={12}/> Fill</button>
                    )}
                    {layer.type !== 'render' && (
                      <button onClick={() => handleUpdate({ interactionMode: 'eyedropper' })} className={`px-4 py-1.5 rounded-full text-[10px] font-bold tracking-wider flex items-center gap-1.5 transition-all ${layer.interactionMode === 'eyedropper' ? 'bg-white text-black shadow-[0_0_12px_rgba(255,255,255,0.3)]' : 'text-text-dim hover:text-white'}`}><Pipette size={12}/> Dropper</button>
                    )}
                    <div className="w-[1px] h-4 bg-white/20 mx-1"></div>
                    <button onClick={() => undo(layer.id)} disabled={!layer.undoStack?.length} className="p-1.5 rounded-full text-[#aaa] hover:text-white transition-all disabled:opacity-30 disabled:cursor-not-allowed" title="Undo"><Undo2 size={12}/></button>
                    <button onClick={() => redo(layer.id)} disabled={!layer.redoStack?.length} className="p-1.5 rounded-full text-[#aaa] hover:text-white transition-all disabled:opacity-30 disabled:cursor-not-allowed" title="Redo"><Redo2 size={12}/></button>
                  </>
                )}
                {layer.type !== 'sketch' && (
                  <>
                    <div className="w-[1px] h-4 bg-white/20 mx-2"></div>
                    <div className="flex items-center gap-3 pr-2">
                      <button onClick={() => { if (layer.type === 'render') { handleUpdate({ compareSource: compSource === 'base' ? 'sketch' : 'base' }); } }} className={`text-[9px] uppercase font-mono tracking-widest ${layer.type === 'render' ? 'cursor-pointer hover:text-white' : ''} text-[#aaa] min-w-[30px] text-right font-bold`}>
                         {layer.type === 'render' && compSource === 'sketch' ? 'Sketch' : 'Base'}
                      </button>
                      <div className="relative flex items-center group/slider">
                        <input type="range" min="0" max="100" value={wipeVal} onChange={(e) => handleUpdate({ wipe: parseInt(e.target.value) })} className="w-32 appearance-none bg-[#333] h-[3px] rounded-full outline-none [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3 [&::-webkit-slider-thumb]:h-3 [&::-webkit-slider-thumb]:bg-white [&::-webkit-slider-thumb]:rounded-full cursor-ew-resize hover:bg-[#444] transition-colors" />
                      </div>
                      <span className="text-[9px] uppercase font-mono tracking-widest text-white min-w-[30px] font-bold">
                        {layer.type === 'render' ? 'Render' : 'Vector'}
                      </span>
                      <button onClick={() => handleUpdate({ compareMode: compMode === 'wipe' ? 'fade' : compMode === 'fade' ? 'blend' : 'wipe' })} className="text-[#aaa] hover:text-white transition-colors flex items-center gap-1 text-[9px] uppercase font-mono tracking-widest font-bold ml-1">
                        {compMode === 'wipe' ? <><SplitSquareHorizontal size={12}/> Wipe</> : compMode === 'fade' ? <><Blend size={12}/> Fade</> : <><Layers size={12}/> Blend</>}
                      </button>
                    </div>
                  </>
                )}
              </div>

              <div className="absolute inset-0 w-full h-full relative flex items-center justify-center min-h-0 min-w-0 bg-transparent">
              <PanZoom transform={panZoomTransform} setTransform={setPanZoomTransform}>
                <div className={`relative inline-block select-none touch-none ${selectedImage ? 'cursor-crosshair' : ''} ${layer.interactionMode === 'sketch' ? 'no-drag' : ''}`} onClick={(e) => handleImageClick(e, layer)} onPointerDown={e => handlePointerDown(e, layer)} onPointerMove={e => handlePointerMove(e, layer)} onPointerUp={e => handlePointerUp(e, layer)} onPointerCancel={e => handlePointerCancel(e, layer)}>
                  <img ref={el => { if(el) imageRefs.current[layer.id] = el; }} src={displayedImage || ''} alt="Content" className="block w-auto h-auto max-w-full max-h-[80vh] lg:max-h-[calc(100vh-160px)] object-contain pointer-events-none" draggable={false} />
                  {(layer.type === 'vector' || layer.type === 'sketch') && layer.sketchStrokes.length > 0 && (
                    <svg className={`absolute inset-0 w-full h-full pointer-events-none ${layer.hideEdits ? 'hidden' : ''}`} viewBox="0 0 100 100" preserveAspectRatio="none">
                      {layer.sketchStrokes.filter(s => s && s.points).map(stroke => (
                         <polyline key={stroke.id} points={stroke.points.map(p => `${p.x},${p.y}`).join(' ')} fill="none" stroke={stroke.color} strokeWidth={stroke.width || 0.5} strokeLinecap="round" strokeLinejoin="round" />
                      ))}
                    </svg>
                  )}
                  <div className="absolute inset-0 pointer-events-none flex items-center justify-center overflow-hidden" style={compMode === 'wipe' ? { clipPath: `polygon(${wipeVal}% 0, 100% 0, 100% 100%, ${wipeVal}% 100%)` } : compMode === 'blend' ? { opacity: (100 - wipeVal) / 100, mixBlendMode: 'multiply' } : { opacity: (100 - wipeVal) / 100 }}>
                    <img src={sourceImg} alt="Overlay Context" className="block w-full h-full object-contain pointer-events-none" draggable={false} />
                  </div>
                  {(compMode === 'wipe' && wipeVal > 0 && wipeVal < 100) && (
                    <div className="absolute top-0 bottom-0 w-[1.5px] bg-white z-20 pointer-events-none drop-shadow-md" style={{ left: `${wipeVal}%` }} />
                  )}
                  {!layer.hideEdits && layer.annotations.map((ann, i) => (
                    <div key={ann.id} className="no-screenshot annotation-node absolute z-20 flex flex-col items-center" style={{ left: `${ann.x}%`, top: `${ann.y}%`, transform: 'translate(-50%, -50%)' }}>
                      {/* Stylized label: White BG with black text and circles as requested */}
                      <div onClick={(e) => { e.stopPropagation(); toggleAnnotationOpen(layer.id, ann.id); }} className="w-6 h-6 rounded-full bg-white border-[2px] border-black flex items-center justify-center text-[11px] font-bold text-black cursor-pointer shadow-lg hover:scale-110 ring-1 ring-white/10">
                        {i + 1}
                      </div>
                       {ann.isOpen && (
                        <div className="absolute top-8 left-1/2 -translate-x-1/2 bg-[#1a1a1a] border border-white/20 rounded-xl shadow-2xl p-3 w-56 animate-in fade-in zoom-in-95 duration-200 backdrop-blur-xl">
                           <div className="flex justify-between items-center mb-2.5 px-1">
                             <span className="text-[10px] uppercase font-bold text-white tracking-[0.15em] opacity-90">Annotation {i + 1}</span>
                             <button onClick={(e) => { e.stopPropagation(); toggleAnnotationOpen(layer.id, ann.id, false); }} className="text-[#888] hover:text-white transition-colors p-1 -mr-1"><X size={14} /></button>
                           </div>
                           <textarea autoFocus className="w-full bg-[#080808] text-[11px] text-white font-mono placeholder-[#555] rounded-lg p-2.5 resize-none focus:outline-none custom-scrollbar border border-white/10 focus:border-white/30 transition-colors" placeholder="e.g. Wrap in copper wire..." rows={3} value={ann.text} onChange={(e) => updateAnnotationText(layer.id, ann.id, e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); toggleAnnotationOpen(layer.id, ann.id, false); } }} />
                           <div className="flex justify-between items-center mt-3 pt-1.5 px-1 border-t border-white/5">
                             <button onClick={(e) => { e.stopPropagation(); deleteAnnotation(layer.id, ann.id); }} className="text-[#ff5555] opacity-70 hover:opacity-100 text-[9px] uppercase tracking-[0.1em] font-bold transition-opacity">Remove</button>
                             <button onClick={(e) => { e.stopPropagation(); toggleAnnotationOpen(layer.id, ann.id, false); }} className="bg-white text-black px-2.5 py-1 rounded-md opacity-90 hover:opacity-100 text-[9px] uppercase tracking-[0.1em] font-bold flex items-center gap-1 transition-all"><Check size={10} strokeWidth={3} /> Save</button>
