                         <option value="3:4">Vertical (3:4)</option>
                     </select>
                  </div>
                  {(layer.canvasAspect || canvasAspect) !== 'original' && (
                  <div className="flex flex-col gap-2">
                     <label className="text-[9px] uppercase tracking-widest text-[#777] font-mono">Background Color</label>
                     <div className="relative">
                       <input type="color" value={layer.canvasBgColor || canvasBgColor} onChange={e => { if (layer.isBlankCanvas) { handleUpdate({ canvasBgColor: e.target.value }); } else { setCanvasBgColor(e.target.value); } }} className="w-full h-8 cursor-pointer rounded-sm bg-transparent border border-white/10 outline-none p-0 appearance-none [&::-webkit-color-swatch-wrapper]:p-0 [&::-webkit-color-swatch]:border-none" />
                     </div>
                  </div>
                  )}
                </div>
              )}
              {layer.images.length > 0 && layer.type === 'sketch' && !layer.isBlankCanvas && (
                <div className="flex flex-col gap-4 mt-[-10px]">
                  <button onClick={handleGallerySelect} className="w-full py-2.5 px-4 text-[10px] font-bold tracking-[0.1em] uppercase border border-border/50 border-dashed rounded-sm text-[#888] hover:text-white hover:border-white/50 hover:bg-white/5 transition-all flex justify-center items-center gap-2">
                    <ImageIcon size={12}/> Replace Source Image
                  </button>
                </div>
              )}
              <div className="flex flex-col gap-6">
                {layer.type !== 'sketch' && (
                  <>
                    <div className="flex flex-col gap-3">
                      <div className="text-[10px] uppercase tracking-widest text-[#aaa] font-mono flex items-center justify-between pb-2 border-b border-white/5">
                        <span>AI Settings</span>
                        <div className="relative">
                          <select className="appearance-none bg-transparent hover:bg-white/5 border border-transparent hover:border-white/10 text-white text-[9px] uppercase tracking-widest font-mono py-1 pl-2 pr-6 rounded transition-colors cursor-pointer outline-none" value={renderSettings.model} onChange={e => setRenderSettings({ ...renderSettings, model: e.target.value })}>
                            <option value="gemini-3-pro-image-preview">Nano Banana Pro</option>
                            <option value="gemini-2.5-flash-image">Nano Banana 2</option>
                            <option value="gemini-2.5-pro-image">Nano Banana Pro (Legacy)</option>
                          </select>
                          <ChevronDown size={10} className="absolute right-1 top-1/2 -translate-y-1/2 text-[#777] pointer-events-none" />
                        </div>
                      </div>
                      <div className="flex flex-col gap-2">
                        <label className="text-[9px] uppercase tracking-widest text-[#777] font-mono">Guiding Prompt</label>
                        <textarea className="w-full bg-bg border border-border/50 rounded-sm p-3 text-[11px] text-text-main font-mono placeholder-[#444] resize-none focus:outline-none focus:border-white/50 transition-colors" rows={3} placeholder="e.g., Refine edges, minimalist style..." value={layer.promptDetails} onChange={e => handleUpdate({ promptDetails: e.target.value })} />
                      </div>
                    </div>
                    <div className="flex flex-col gap-3">
                      <div className="text-[10px] uppercase tracking-widest text-[#aaa] font-mono pb-2 border-b border-white/5">
                        Render Output Settings
                      </div>
                      {layer.type !== 'render' && (
                        <div className="flex flex-col gap-2">
                          <label className="text-[9px] uppercase tracking-widest text-[#777] font-mono">Style</label>
                          <select className="w-full bg-bg border border-border/50 text-white text-[10px] p-2 rounded-sm cursor-pointer focus:outline-none focus:border-white/50 appearance-none font-mono" value={renderSettings.renderStyle} onChange={e => setRenderSettings({ ...renderSettings, renderStyle: e.target.value })}>
                            {RENDER_STYLES.map(style => (<option key={style.id} value={style.id}>{style.name}</option>))}
                          </select>
                        </div>
                      )}

                      {/* CUSTOM AESTHETIC TEXTAREA */}
                      {layer.type !== 'render' && renderSettings.renderStyle === 'custom' && (
                        <div className="flex flex-col gap-2 animate-in fade-in slide-in-from-top-2 duration-300">
                          <div className="flex items-center justify-between">
                            <label className="text-[9px] uppercase tracking-widest text-[#777] font-mono">Custom Aesthetic</label>
                            <button 
                              onClick={handleEnhanceCustomPrompt} 
                              disabled={isEnhancing || !renderSettings.customAesthetic.trim()}
                              className="text-white/60 hover:text-white transition-colors flex items-center gap-1 text-[8px] uppercase tracking-widest font-mono disabled:opacity-30"
                            >
                              {isEnhancing ? <Loader2 size={10} className="animate-spin" /> : <Sparkles size={10} />}
                              Enhance
                            </button>
                          </div>
                          <textarea 
                            className="w-full bg-bg border border-border/50 rounded-sm p-3 text-[10px] text-text-main font-mono placeholder-[#444] resize-none focus:outline-none focus:border-white/50 transition-colors"
                            rows={4}
                            placeholder="Describe materials, lighting, and mood (e.g., PS1 low-poly graphics, brutalist concrete...)"
                            value={renderSettings.customAesthetic}
                            onChange={e => setRenderSettings(prev => ({ ...prev, customAesthetic: e.target.value }))}
                          />
                        </div>
                      )}

                      {layer.type !== 'render' && (
                        <div className="flex flex-col gap-2">
                          <label className="text-[9px] uppercase tracking-widest text-[#777] font-mono">Aspect Ratio</label>
                          <select className="w-full bg-bg border border-border/50 text-text-main text-[10px] p-2 rounded-sm focus:outline-none focus:border-white/50 appearance-none font-mono" value={renderSettings.aspectRatio} onChange={e => setRenderSettings({ ...renderSettings, aspectRatio: e.target.value })}>
                            <option value="auto">Auto (Match Input)</option>
                            <option value="1:1">1:1 Square</option>
                            <option value="16:9">16:9 Cinematic</option>
                            <option value="9:16">9:16 Vertical</option>
                            <option value="4:3">4:3 Standard</option>
                          </select>
                        </div>
                      )}
                      <div className="flex items-center justify-between pt-1">
                        <span className="text-[9px] uppercase font-mono text-[#777] tracking-widest cursor-pointer select-none" onClick={() => setRenderSettings({ ...renderSettings, renderBackground: !renderSettings.renderBackground })}>
                          Contextual Background
                        </span>
                        <button onClick={() => setRenderSettings({ ...renderSettings, renderBackground: !renderSettings.renderBackground })} className={`w-8 h-4 rounded-full flex items-center p-0.5 transition-colors ${renderSettings.renderBackground ? 'bg-white' : 'bg-bg border border-border/50'}`}>
                          <div className={`w-3 h-3 rounded-full transition-transform ${renderSettings.renderBackground ? 'bg-black translate-x-4' : 'bg-white translate-x-0'}`} />
                        </button>
                      </div>
                    </div>
                  </>
                )}
                <div className="flex flex-col gap-2">
                  {layer.type === 'sketch' ? (
                    <button disabled={layer.isGenerating} onClick={() => executeVector(layer.id)} className={`w-full py-4 px-6 text-[10px] uppercase tracking-[0.2em] font-bold flex items-center justify-between transition-all rounded-sm bg-white text-black hover:bg-[#e0e0e0] shadow-[0_0_15px_rgba(255,255,255,0.2)] hover:shadow-[0_0_25px_rgba(255,255,255,0.4)] disabled:opacity-50 group hover:-translate-y-0.5`}>
                      <span>Generate Vector Layer</span>
                      < Wand2 size={14} className="group-hover:rotate-12 transition-transform" />
                    </button>
                  ) : layer.type === 'vector' ? (
                    <>
                      <button disabled={layer.isGenerating} onClick={() => executeRender(layer.id)} className={`w-full py-4 px-6 text-[10px] uppercase tracking-[0.2em] font-bold flex items-center justify-between transition-all rounded-sm bg-white text-black hover:bg-[#e0e0e0] shadow-[0_0_15px_rgba(255,255,255,0.2)] hover:shadow-[0_0_25px_rgba(255,255,255,0.4)] disabled:opacity-50 hover:-translate-y-0.5 group`}>
                        <span>Generate Render</span>
                        <Wand2 size={14} className="group-hover:rotate-12 transition-transform" />
                      </button>
                      <div className="flex items-center justify-center my-2 relative">
                         <div className="absolute w-full h-px bg-border/40"></div>
                         <span className="relative z-10 bg-black/80 border border-white/10 rounded-full px-2.5 py-0.5 text-[8px] font-mono tracking-widest text-[#777] uppercase">OR</span>
                      </div>
                      <button disabled={layer.isGenerating} onClick={() => executeVector(layer.id)} className={`w-full py-3 px-6 text-[9px] uppercase tracking-[0.2em] font-bold flex items-center justify-center gap-2 transition-all rounded-sm bg-transparent text-white border border-border/50 hover:border-white/50 hover:bg-white/5 disabled:opacity-50`}>
                        <PenTool size={12} />
                        <span>Refine Vector</span>
                      </button>
                    </>
                  ) : (
                    <button disabled={layer.isGenerating} onClick={() => executeRender(layer.id)} className={`w-full py-4 px-6 text-[10px] uppercase tracking-[0.2em] font-bold flex items-center justify-between transition-all rounded-sm bg-white text-black hover:bg-[#e0e0e0] shadow-[0_0_15px_rgba(255,255,255,0.2)] hover:shadow-[0_0_25px_rgba(255,255,255,0.4)] disabled:opacity-50 hover:-translate-y-0.5 group`}>
                      <span>Refine Render</span>
                      <Wand2 size={14} className="group-hover:rotate-12 transition-transform" />
                    </button>
                  )}
                </div>
                {layer.type !== 'sketch' && (
                  <>
                    <div className="w-full h-[1px] bg-border/40 my-1 mt-2"></div>
                    <button onClick={() => downloadFullImage(displayedImage || '', layer)} disabled={layer.isGenerating} className="w-full py-3 px-6 mt-1 text-[10px] uppercase tracking-[0.2em] font-bold flex items-center justify-between transition-all rounded-sm bg-black text-white hover:bg-[#1a1a1a] border border-border/60 hover:border-white/50 shadow-lg disabled:opacity-50 hover:-translate-y-0.5">
                      <span>Export to Gallery</span>
                      <Download size={14} />
                    </button>
                  </>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </section>
  );
};

