import React, { useState, useRef, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { Loader2, Trash2 } from 'lucide-react';
import { LayerData, RenderSettings, Annotation, ColorEdit, SketchStroke, GRAYMAP_LEVELS } from './types';
import { renderEditsToDataURL, createCompositeDataURL, VECTOR_PROMPTS, RENDER_STYLES, BASE_RENDER_CONSTRAINT, getClosestAspectRatio } from './utils';
import { LayerSection } from './LayerSection';
import { TransformState } from './PanZoom';

export default function App() {
  const [globalTransform, setGlobalTransform] = useState<TransformState>({ scale: 0.7, x: 0, y: 0 });
  const [layers, setLayers] = useState<LayerData[]>([{
    id: 'init',
    type: 'sketch',
    images: [],
    selectedIndex: 0,
    annotations: [],
    colorEdits: [],
    sketchStrokes: [],
    promptDetails: '',
    wipe: 100,
    compareMode: 'wipe',
    interactionMode: 'pins',
    hideEdits: false,
    editedImage: null,
    isGenerating: false,
  }]);

  const [activeStage, setActiveStage] = useState<number>(0);
  const [renderSettings, setRenderSettings] = useState<RenderSettings>({
    aspectRatio: 'auto',
    renderQuality: 'Ultra-High (4k macro detail)',
    renderStyle: '3d-render',
    customAesthetic: '',
    renderBackground: false,
    model: 'Nano Banana Pro'
  });

  const imageRefs = useRef<Record<string, HTMLImageElement | null>>({});
  const [isDragging, setIsDragging] = useState(false);

  const [strokeColor, setStrokeColor] = useState<string>('#000000');
  const [strokeWidth, setStrokeWidth] = useState<number>(3);
  const currentStrokeRef = useRef<SketchStroke | null>(null);
  const [activeEditId, setActiveEditId] = useState<string | null>(null);

  const updateLayer = (id: string, updates: Partial<LayerData>) => {
    setLayers(prev => prev.map(l => l.id === id ? { ...l, ...updates } : l));
  };

  const commitLayerState = (layerId: string) => {
    setLayers(prev => prev.map(l => {
      if (l.id === layerId) {
        const stateToSave = {
          sketchStrokes: [...l.sketchStrokes],
          colorEdits: [...l.colorEdits],
          annotations: [...l.annotations]
        };
        return { ...l, undoStack: [...(l.undoStack || []), stateToSave], redoStack: [] };
      }
      return l;
    }));
  };

  const undo = (layerId: string) => {
    setLayers(prev => prev.map(l => {
      if (l.id === layerId && l.undoStack && l.undoStack.length > 0) {
        const lastState = l.undoStack[l.undoStack.length - 1];
        const currentState = { sketchStrokes: [...l.sketchStrokes], colorEdits: [...l.colorEdits], annotations: [...l.annotations] };
        return {
          ...l,
          sketchStrokes: lastState.sketchStrokes,
          colorEdits: lastState.colorEdits,
          annotations: lastState.annotations,
          undoStack: l.undoStack.slice(0, -1),
          redoStack: [...(l.redoStack || []), currentState]
        };
      }
      return l;
    }));
  };

  const redo = (layerId: string) => {
    setLayers(prev => prev.map(l => {
      if (l.id === layerId && l.redoStack && l.redoStack.length > 0) {
        const nextState = l.redoStack[l.redoStack.length - 1];
        const currentState = { sketchStrokes: [...l.sketchStrokes], colorEdits: [...l.colorEdits], annotations: [...l.annotations] };
        return {
          ...l,
          sketchStrokes: nextState.sketchStrokes,
          colorEdits: nextState.colorEdits,
          annotations: nextState.annotations,
          redoStack: l.redoStack.slice(0, -1),
          undoStack: [...(l.undoStack || []), currentState]
        };
      }
      return l;
    }));
  };

  const scrollToLayer = (index: number) => {
    setActiveStage(index);
  };

  const fileToBase64 = async (url: string): Promise<string> => {
    const res = await fetch(url);
    const blob = await res.blob();
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(blob);
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = error => reject(error);
    });
  };

  const generateImageWithGemini = async (base64Image: string, promptText: string, model: string = 'Nano Banana Pro', temperature: number = 0.5, aspectRatio: string = "1:1") => {
    const safePrompt = promptText.length > 3950 ? promptText.slice(0, 3950) + "..." : promptText;
    const { mediaId: sourceId } = await Flow.save({ base64: base64Image, mimeType: 'image/jpeg' });
    const result = await Flow.generate.image({
      prompt: safePrompt,
      referenceImageMediaIds: [sourceId],
      modelDisplayName: model,
      aspectRatio: (aspectRatio as any) === 'auto' ? '1:1' : (aspectRatio as any),
    });
    if (result?.base64 && result?.mimeType) {
      return `data:${result.mimeType};base64,${result.base64}`;
    }
    throw new Error("No image data returned from Flow.generate.image.");
  };

  const processFile = (file: File) => {
    if (file && file.type.startsWith('image/')) {
      const imageUrl = URL.createObjectURL(file);
      const activeLayer = layers[activeStage] || layers[0];
      if (activeLayer.images.length === 0) {
        setGlobalTransform({ scale: 0.7, x: 0, y: 0 }); 
      }
      updateLayer(activeLayer.id, {
        images: [imageUrl],
        selectedIndex: 0,
        interactionMode: 'sketch'
      });
    }
  };

  const executeVector = async (sourceId: string, customPrompt?: string) => {
    const sourceLayer = layers.find(l => l.id === sourceId);
    if (!sourceLayer) return;
    let sourceImg = sourceLayer.editedImage || sourceLayer.images[sourceLayer.selectedIndex] || sourceLayer.images[0];
    if (!sourceImg) return;
    if (sourceLayer.sketchStrokes.length > 0) {
       sourceImg = await renderEditsToDataURL(sourceLayer.images[sourceLayer.selectedIndex], sourceLayer.colorEdits, sourceLayer.sketchStrokes);
    }

    const newLayerId = Date.now().toString();
    const aspect = renderSettings.aspectRatio === 'auto' ? await getClosestAspectRatio(sourceImg) : renderSettings.aspectRatio;
    const details = customPrompt || sourceLayer.promptDetails;
    const finalPrompt = VECTOR_PROMPTS[0].prompt + (details ? `\n\nCRITICAL ADDITIONAL INSTRUCTIONS:\n${details}` : '');

    const newLayer: LayerData = {
      id: newLayerId, type: 'vector', images: [], selectedIndex: 0, annotations: [], colorEdits: [], sketchStrokes: [], promptDetails: '', wipe: 100, compareMode: 'wipe', interactionMode: 'pins', hideEdits: false, editedImage: null, isGenerating: true, sourceImage: sourceImg,
      generationPrompt: finalPrompt,
      generationModel: renderSettings.model,
      generationAspect: aspect,
      generationTemp: 0.6
    };

    setLayers(prev => [...prev, newLayer]);
    setTimeout(() => scrollToLayer(layers.length), 50);

    try {
      const base64 = await fileToBase64(sourceImg);
      const promises = Array(4).fill(0).map(() => generateImageWithGemini(base64, finalPrompt, renderSettings.model, 0.6, aspect));
      const results = await Promise.all(promises);
      updateLayer(newLayerId, { images: results, isGenerating: false });
    } catch (err) {
      console.error(err);
      updateLayer(newLayerId, { isGenerating: false });
      setLayers(prev => prev.filter(l => l.id !== newLayerId));
    }
  };

  const compileAnnotationPromptWithGemini = async (base64Image: string, activeAnns: Annotation[]): Promise<string> => {
    const notes = activeAnns.map((a, i) => `[Pin ${i + 1} at X:${Math.round(a.x)}% Y:${Math.round(a.y)}%]: "${a.text}"`).join('\n');
    const promptText = `Analyze these technical design pins for an image generation model:
    ${notes}

    Convert these notes into a extremely concise block of descriptive instructions for the model. 
    Focus strictly on materials and localized physical details. 
    Maintain spatial mapping (X/Y coordinates) if relevant.
    OUTPUT MUST BE UNDER 800 CHARACTERS.`;

    try {
      const { text } = await Flow.generate.text(promptText, {
        thinkingLevel: 'medium',
      });
      return text || notes;
    } catch (e) {
      return notes;
    }
  };

  const executeRender = async (sourceId: string) => {
    const sourceLayer = layers.find(l => l.id === sourceId);
    if (!sourceLayer) return;
    let sourceImg = sourceLayer.editedImage || sourceLayer.images[sourceLayer.selectedIndex] || sourceLayer.images[0];
    if (!sourceImg) return;

    if (sourceLayer.sketchStrokes.length > 0) {
       sourceImg = await renderEditsToDataURL(sourceLayer.images[sourceLayer.selectedIndex], sourceLayer.colorEdits, sourceLayer.sketchStrokes);
    }

    const sketchLayer = layers.find(l => l.type === 'sketch');
    let sketchImg = sketchLayer ? (sketchLayer.editedImage || sketchLayer.images[sketchLayer.selectedIndex] || sketchLayer.images[0]) : sourceImg;
    if (sketchLayer && sketchLayer.sketchStrokes.length > 0) {
      sketchImg = await renderEditsToDataURL(sketchLayer.images[sketchLayer.selectedIndex], sketchLayer.colorEdits, sketchLayer.sketchStrokes);
    }

    const newLayerId = Date.now().toString();
    const aspect = renderSettings.aspectRatio === 'auto' ? await getClosestAspectRatio(sourceImg) : renderSettings.aspectRatio;

    try {
      const base64 = await fileToBase64(sourceImg);
      const targetStylePrompt = renderSettings.renderStyle === 'custom' ? renderSettings.customAesthetic : (RENDER_STYLES.find(s => s.id === renderSettings.renderStyle)?.prompt || RENDER_STYLES[0].prompt);
      let finalRenderPrompt = `${BASE_RENDER_CONSTRAINT}\n\n[FINAL AESTHETIC STYLE]\n${targetStylePrompt}`;

      if (!renderSettings.renderBackground) finalRenderPrompt += `\n\n[BACKGROUND CONTEXT]\nCRITICAL: Isolated background.`;

      const globalDetails = sourceLayer.promptDetails.trim();
      if (globalDetails) {
        finalRenderPrompt += `\n\nADDITIONAL GLOBAL INSTRUCTIONS:\n${globalDetails.slice(0, 1000)}`;
      }

      const activeAnns = sourceLayer.annotations.filter(a => a.text.trim() !== '');
      if (activeAnns.length > 0) {
        const addon = await compileAnnotationPromptWithGemini(base64, activeAnns);
        finalRenderPrompt += `\n\nCRITICAL REGION-SPECIFIC DIRECTIVES:\n${addon}`;
      }

      finalRenderPrompt += `\n\n[OUTPUT CONFIGURATION]\nQuality: ${renderSettings.renderQuality}.`;

      const newLayer: LayerData = {
        id: newLayerId, type: 'render', images: [], selectedIndex: 0, annotations: [], colorEdits: [], sketchStrokes: [], promptDetails: '', wipe: 100, compareMode: 'wipe', compareSource: 'base', interactionMode: 'pins', hideEdits: false, editedImage: null, isGenerating: true, sourceImage: sourceImg, baseSketchImage: sketchImg,
        generationPrompt: finalRenderPrompt,
        generationModel: renderSettings.model,
        generationAspect: aspect,
        generationTemp: 0.4
      };

      setLayers(prev => [...prev, newLayer]);
      setTimeout(() => scrollToLayer(layers.length), 50);

      const promises = Array(4).fill(0).map(() => generateImageWithGemini(base64, finalRenderPrompt, renderSettings.model, 0.4, aspect));
      const results = await Promise.all(promises);
      updateLayer(newLayerId, { images: results, isGenerating: false });
    } catch (err) {
      console.error(err);
      updateLayer(newLayerId, { isGenerating: false });
      setLayers(prev => prev.filter(l => l.id !== newLayerId));
    }
  };

  const generateAlternatives = async (layerId: string) => {
    const layer = layers.find(l => l.id === layerId);
    if (!layer || (layer.type !== 'vector' && layer.type !== 'render')) return;

    const sourceImg = layer.sourceImage;
    if (!sourceImg) return;

    updateLayer(layerId, { isGenerating: true });
    try {
      const base64 = await fileToBase64(sourceImg);

      // PERSISTENCE FIX: Prioritize stored generation parameters to ensure "New Alts" stay faithful to instructions
      const model = layer.generationModel || renderSettings.model;
      const aspect = layer.generationAspect || (renderSettings.aspectRatio === 'auto' ? await getClosestAspectRatio(sourceImg) : renderSettings.aspectRatio);
      const temp = layer.generationTemp || (layer.type === 'vector' ? 0.6 : 0.4);

      let finalPrompt = layer.generationPrompt;
      if (!finalPrompt) {
        // Fallback for layers created before this update
        if (layer.type === 'vector') {
          finalPrompt = VECTOR_PROMPTS[0].prompt + (layer.promptDetails ? `\n\nCRITICAL ADDITIONAL INSTRUCTIONS:\n${layer.promptDetails}` : '');
        } else {
          const targetStylePrompt = renderSettings.renderStyle === 'custom' ? renderSettings.customAesthetic : (RENDER_STYLES.find(s => s.id === renderSettings.renderStyle)?.prompt || RENDER_STYLES[0].prompt);
          finalPrompt = `${BASE_RENDER_CONSTRAINT}\n\n[FINAL AESTHETIC STYLE]\n${targetStylePrompt}`;
          if (!renderSettings.renderBackground) finalPrompt += `\n\n[BACKGROUND CONTEXT]\nCRITICAL: Isolated background.`;
          if (layer.promptDetails.trim()) finalPrompt += `\n\nADDITIONAL GLOBAL INSTRUCTIONS:\n${layer.promptDetails.trim().slice(0, 1000)}`;
          finalPrompt += `\n\n[OUTPUT CONFIGURATION]\nQuality: ${renderSettings.renderQuality}.`;
        }
      }

      const promises = Array(4).fill(0).map(() => generateImageWithGemini(base64, finalPrompt!, model, temp, aspect));
      const results = await Promise.all(promises);
      updateLayer(layerId, { images: [...layer.images, ...results], isGenerating: false });
    } catch (err) {
      console.error(err);
      updateLayer(layerId, { isGenerating: false });
    }
  };

  const [spaceHeld, setSpaceHeld] = useState(false);
  useEffect(() => {
    const down = (e: KeyboardEvent) => { if (e.code === 'Space' && !(e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement)) setSpaceHeld(true); };
    const up = (e: KeyboardEvent) => { if (e.code === 'Space') setSpaceHeld(false); };
    window.addEventListener('keydown', down); window.addEventListener('keyup', up);
    return () => { window.removeEventListener('keydown', down); window.removeEventListener('keyup', up); };
  }, []);

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>, layer: LayerData) => {
    if (e.shiftKey || e.button === 1 || spaceHeld) return; 
    if (layer.images.length === 0 || layer.isGenerating || layer.interactionMode !== 'sketch') return;

    e.preventDefault();

    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    if (!Number.isFinite(x) || !Number.isFinite(y)) return;
    commitLayerState(layer.id);
    const newStroke: SketchStroke = { id: `stroke-${Date.now()}-${Math.random()}`, points: [{x, y}], color: strokeColor, width: strokeWidth };
    currentStrokeRef.current = newStroke;
    updateLayer(layer.id, { sketchStrokes: [...layer.sketchStrokes, newStroke] });
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch {}
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>, layer: LayerData) => {
    if (layer.interactionMode !== 'sketch' || !currentStrokeRef.current) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    currentStrokeRef.current.points.push({x, y});
    const updateId = currentStrokeRef.current.id;
    const updatedPoints = [...currentStrokeRef.current.points];
    setLayers(prev => prev.map(l => l.id === layer.id ? { ...l, sketchStrokes: l.sketchStrokes.map(s => s.id === updateId ? { ...s, points: updatedPoints } : s) } : l));
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>, layer: LayerData) => {
    if (layer.interactionMode !== 'sketch') return;
    currentStrokeRef.current = null;
    try { if (e.currentTarget.hasPointerCapture(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId); } catch {}
  };

  const handlePointerCancel = handlePointerUp;

  const handleImageClick = (e: React.MouseEvent<HTMLDivElement>, layer: LayerData) => {
    if (e.shiftKey || e.button === 1) return;
    if (layer.images.length === 0 || layer.isGenerating) return;
    if ((e.target as HTMLElement).closest('.annotation-node')) return;
    if (layer.interactionMode === 'sketch') return;

    if (layer.interactionMode === 'fill' || layer.interactionMode === 'eyedropper' || layer.interactionMode === 'recolor') {
        const imgElement = imageRefs.current[layer.id];
        if (!imgElement) return;
        const rect = imgElement.getBoundingClientRect();
        const imgRatio = imgElement.naturalWidth / imgElement.naturalHeight;
        const boxRatio = rect.width / rect.height;
        let drawW = rect.width, drawH = rect.height, offsetX = 0, offsetY = 0;
        if (imgRatio > boxRatio) { drawH = rect.width / imgRatio; offsetY = (rect.height - drawH) / 2; }
        else { drawW = rect.height * imgRatio; offsetX = (rect.width - drawW) / 2; }
        const cx = e.clientX - rect.left - offsetX, cy = e.clientY - rect.top - offsetY;
        if (cx < 0 || cx > drawW || cy < 0 || cy > drawH) return;
        const nx = Math.floor((cx / drawW) * imgElement.naturalWidth);
        const ny = Math.floor((cy / drawH) * imgElement.naturalHeight);

        const canvas = document.createElement('canvas');
        canvas.width = imgElement.naturalWidth; canvas.height = imgElement.naturalHeight;
        const ctx = canvas.getContext('2d'); if (!ctx) return;

        const tempImg = new Image(); tempImg.crossOrigin = "Anonymous";
        tempImg.onload = () => {
            ctx.drawImage(tempImg, 0, 0); const pixel = ctx.getImageData(nx, ny, 1, 1).data;
            if (pixel[3] === 0) return;

            if (layer.interactionMode === 'eyedropper') {
                const hex = '#' + [pixel[0], pixel[1], pixel[2]].map(x => x.toString(16).padStart(2, '0')).join('');
                setStrokeColor(hex);
                return;
            }

            const newEditId = Date.now().toString();
            const hexToRgb = (hex: string): [number, number, number] => {
               const r = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
               return r ? [parseInt(r[1], 16), parseInt(r[2], 16), parseInt(r[3], 16)] : [0,0,0];
            };
            const rgbColor = hexToRgb(strokeColor);

            commitLayerState(layer.id);
            const newEdit: ColorEdit = { id: newEditId, type: 'fill', originX: nx, originY: ny, originColor: [pixel[0], pixel[1], pixel[2]], tolerance: 20, newColor: rgbColor };
            updateLayer(layer.id, { colorEdits: [...layer.colorEdits, newEdit] });
            setActiveEditId(newEditId);
        };
        tempImg.src = layer.editedImage || layer.images[layer.selectedIndex]; return;
    }
    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100; const y = ((e.clientY - rect.top) / rect.height) * 100;
    commitLayerState(layer.id);
    updateLayer(layer.id, { annotations: [...layer.annotations, { id: Date.now().toString(), x, y, text: '', isOpen: true }] });
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      if ((e.metaKey || e.ctrlKey) && e.key === 'z') {
        e.preventDefault();
        const layer = layers[activeStage];
        if (!layer) return;
        if (e.shiftKey) {
          redo(layer.id);
        } else {
          undo(layer.id);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [layers, activeStage]);

  useEffect(() => {
    const layer = layers[activeStage];
    if (!layer || layer.images.length === 0) return;
    if (layer.colorEdits.length === 0 && layer.sketchStrokes.length === 0) {
      if (layer.editedImage) updateLayer(layer.id, { editedImage: null });
      return;
    }
    let cancelled = false;
    setTimeout(async () => {
      const result = await renderEditsToDataURL(layer.images[layer.selectedIndex], layer.colorEdits, layer.sketchStrokes);
      if (!cancelled) updateLayer(layer.id, { editedImage: result });
    }, 50);
    return () => { cancelled = true; };
  }, [layers[activeStage]?.colorEdits, layers[activeStage]?.sketchStrokes, layers[activeStage]?.selectedIndex, layers[activeStage]?.canvasAspect]);

  const captureScreenshot = async (id: string) => {
    const el = document.getElementById(id);
    if (!el) return;
    try {
      const canvas = document.createElement('canvas');
      const rect = el.getBoundingClientRect();
      canvas.width = rect.width * 2; canvas.height = rect.height * 2;
      const base64 = canvas.toDataURL('image/png').split(',')[1];
      await Flow.save({ base64, mimeType: 'image/png', name: `converge-screenshot-${Date.now()}` });
    } catch (err) { console.error('Screenshot save failed:', err); }
  };

  const downloadFullImage = async (src: string, layer: LayerData) => {
    try {
      const compSource = layer.compareSource || 'base';
      const overlayImg = (compSource === 'sketch' && layer.baseSketchImage) ? layer.baseSketchImage : (layer.sourceImage || layer.images[0]);

      let finalDataUrl = src;
      // SURGICAL FIX: Use createCompositeDataURL to capture the exact canvas state (wipe/fade/blend/strokes)
      if (overlayImg && (layer.wipe < 100 || layer.sketchStrokes.length > 0)) {
         finalDataUrl = await createCompositeDataURL(src, overlayImg, layer.wipe, layer.compareMode, layer.sketchStrokes);
      } else if (layer.sketchStrokes.length > 0) {
         finalDataUrl = await renderEditsToDataURL(src, layer.colorEdits, layer.sketchStrokes);
      }

      const base64 = finalDataUrl.includes('base64,') ? finalDataUrl.split('base64,')[1] : finalDataUrl;
      await Flow.save({ base64, mimeType: 'image/png', name: `converge-${layer.type}-${Date.now()}` });
    } catch (err) { console.error('Download save failed:', err); }
  };

  return (
    <div className="bg-[#080808] text-text-main font-sans min-h-screen relative overflow-hidden">

      <header className="fixed top-0 left-0 right-0 p-6 z-50 flex items-center justify-center pointer-events-none drop-shadow-md">
        <h1 className="font-serif italic text-2xl tracking-[2px] uppercase text-white font-bold max-sm:text-lg">CONVERGE</h1>
      </header>

      <div className="absolute left-0 top-0 bottom-0 z-40 w-full lg:w-[400px] shrink-0 flex flex-col pt-24 pb-8 px-6 animate-in fade-in zoom-in-95 slide-in-from-left-4 duration-500 delay-150 fill-mode-both overflow-y-auto pointer-events-none custom-scrollbar">
        <div className="bg-black/40 backdrop-blur-2xl border border-white/10 p-8 rounded-2xl shadow-2xl flex flex-col gap-6 pointer-events-auto max-h-full overflow-y-auto custom-scrollbar">
          <div className="flex items-center justify-between border-b border-border/30 pb-4 mb-2 hidden lg:flex">
            <span className="text-[10px] uppercase tracking-widest text-[#aaa] font-mono">History Stack</span>
            <button onClick={() => { setLayers([{id: 'init', type: 'sketch', images: [], selectedIndex: 0, annotations: [], colorEdits: [], sketchStrokes: [], promptDetails: '', wipe: 100, compareMode: 'wipe', interactionMode: 'pins', hideEdits: false, editedImage: null, isGenerating: false}]); setActiveStage(0); setActiveEditId(null); }} className="text-[#888] hover:text-[#ff4444] transition-colors text-[9px] uppercase tracking-widest font-mono flex items-center gap-1">
              <Trash2 size={10} /> Clear All
            </button>
          </div>
          {[...layers].reverse().map((l, reversedIndex) => {
            const i = layers.length - 1 - reversedIndex;
            return (
              <div 
                key={l.id} 
                onClick={() => setActiveStage(i)}
                className={`w-full relative group cursor-pointer rounded-lg p-3 transition-all flex items-center gap-4 border ${activeStage === i ? 'bg-white/10 border-white/30' : 'bg-black/20 border-white/5 hover:bg-white/5'}`}
              >
                <div className={`w-16 h-16 shrink-0 rounded border overflow-hidden relative flex items-center justify-center ${activeStage === i ? 'border-white bg-white/20' : 'bg-black/30 border-border/30'}`}>
                   {l.images.length > 0 ? (
                     <img src={l.editedImage || l.images[l.selectedIndex] || l.images[0]} className="w-full h-full object-cover pointer-events-none" alt="layer thumbnail" draggable={false} />
                   ) : l.isGenerating ? (
                     <Loader2 size={14} className="animate-spin text-white" />
                   ) : null}
                   <div className={`absolute bottom-0 right-0 px-1 py-0.5 text-[8px] font-mono text-white/80 rounded-tl ${
                     l.type === 'sketch' ? 'bg-stone-500/80' : 
                     l.type === 'vector' ? 'bg-zinc-500/80' : 
                     'bg-neutral-800/80 border-t border-l border-white/20'
                   }`}>L{i}</div>
                </div>

                <div className="hidden lg:flex flex-col flex-1 min-w-0 pr-6">
                   <div className="flex items-center justify-between pointer-events-none">
                     <span className={`text-[11px] font-bold text-white uppercase tracking-wider truncate border-l-2 pl-2 -ml-2 mb-1 ${
                       l.type === 'sketch' ? 'border-stone-500' : 
                       l.type === 'vector' ? 'border-zinc-500' : 
                       'border-white'
                     }`}>
                       {l.type === 'sketch' ? 'SKETCH' : l.type === 'vector' ? 'VECTOR' : 'RENDER'}
                     </span>
                   </div>
                   <span className="text-[9px] text-text-dim font-mono truncate mt-1">
                     {l.isGenerating ? 'Processing...' : l.images.length > 0 ? `${l.images.length} Variants` : 'Empty'}
                   </span>
                </div>

                {layers.length > 1 && (
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      const newLayers = layers.filter((_, idx) => idx !== i);
                      setLayers(newLayers);
                      if (activeStage === i) {
                         setActiveStage(Math.max(0, i - 1));
                      } else if (activeStage > i) {
                         setActiveStage(activeStage - 1);
                      }
                    }}
                    className="absolute right-2 inset-y-0 my-auto w-7 h-7 flex items-center justify-center pointer-events-auto opacity-0 group-hover:opacity-100 text-[#888] hover:text-[#eee] bg-[#111] hover:bg-[#333] border border-white/10 rounded overflow-hidden transition-all shadow-2xl z-20"
                  >
                    <Trash2 size={13} />
                  </button>
                )}
              </div>
            );
          })}
        </div>
      </div>

      <div className="flex-1 h-screen relative bg-transparent">
        {layers[activeStage] && (
           <LayerSection 
               key={layers[activeStage].id} layer={layers[activeStage]} index={activeStage} isActive={true} fileInputRef={{current: null}} isDragging={isDragging} setIsDragging={setIsDragging} 
               processFile={processFile} executeVector={executeVector} executeRender={executeRender} generateAlternatives={generateAlternatives} updateLayer={updateLayer} renderSettings={renderSettings} setRenderSettings={setRenderSettings}
               handlePointerDown={handlePointerDown} handlePointerMove={handlePointerMove} handlePointerUp={handlePointerUp} handlePointerCancel={handlePointerCancel} handleImageClick={handleImageClick}
               captureScreenshot={captureScreenshot} downloadFullImage={downloadFullImage} imageRefs={imageRefs} strokeColor={strokeColor} setStrokeColor={setStrokeColor} strokeWidth={strokeWidth} setStrokeWidth={setStrokeWidth}
               activeEditId={activeEditId} setActiveEditId={setActiveEditId} scrollToLayer={scrollToLayer}
               deleteEdit={(lid, eid) => { commitLayerState(lid); updateLayer(lid, { colorEdits: layers.find(l=>l.id===lid)!.colorEdits.filter(e => e.id !== eid) }) }}
               deleteAnnotation={(lid, aid) => { commitLayerState(lid); updateLayer(lid, { annotations: layers.find(l=>l.id===lid)!.annotations.filter(a => a.id !== aid) }) }}
               updateAnnotationText={(lid, aid, text) => updateLayer(lid, { annotations: layers.find(l=>l.id===lid)!.annotations.map(a => a.id === aid ? {...a, text} : a) })}
               toggleAnnotationOpen={(lid, aid, state) => updateLayer(lid, { annotations: layers.find(l=>l.id===lid)!.annotations.map(a => a.id === aid ? {...a, isOpen: state !== undefined ? state : !a.isOpen} : a) })}
               undo={undo} redo={redo}
               panZoomTransform={globalTransform} setPanZoomTransform={setGlobalTransform}
           />
        )}
      </div>
    </div>
  );
}
